def relative_ranks(score):
    result=['']*len(score)
    for rank,index in enumerate(sorted(range(len(score)),key=lambda i:score[i],reverse=True),1):
        result[index]=('Gold Medal','Silver Medal','Bronze Medal')[rank-1] if rank<=3 else str(rank)
    return result

